function buildMessage({ name, company, service, caseTitle, visitor, minutes = FREE_MINUTES }) {
  const lines = ['السلام عليكم يا أستاذ أحمد،'];
  if (name && company) lines.push('أنا ' + name + '، من شركة ' + company + '.');
  else if (name) lines.push('أنا ' + name + '.');
  else if (company) lines.push('أتواصل من شركة ' + company + '.');
  const v = visitor || {};
  if (v.sector) lines.push('القطاع: ' + v.sector);
  if (v.country) lines.push('الدولة: ' + v.country);
  if (service) lines.push('الخدمة التي أحتاجها: ' + service);
  if (caseTitle) lines.push('قرأت في موقعك حالة: ' + caseTitle);
  lines.push('أرغب في الجلسة الأولى المجانية (' + minutes + ' دقيقة).');
  return lines.join('\n');
}
const waUrl = (text) => 'https://wa.me/' + WHATSAPP + '?text=' + encodeURIComponent(text);

function Icon({ name, size = 22 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">
      {(ICONS[name] || ICONS.briefcase).map((d, i) => <path key={i} d={d} />)}
    </svg>
  );
}

function useCountUp(target, active) {
  const [value, setValue] = useState(0);
  useEffect(() => {
    if (!active) return undefined;
    const reduced = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduced) { setValue(target); return undefined; }
    let frame = 0;
    const start = performance.now();
    const tick = (now) => {
      const p = Math.min(1, (now - start) / 1300);
      setValue(Math.round(target * (1 - Math.pow(1 - p, 3))));
      if (p < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, active]);
  return value;
}

function useInView() {
  const ref = useRef(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return undefined;
    if (typeof IntersectionObserver === 'undefined') { setSeen(true); return undefined; }
    const io = new IntersectionObserver((entries) => { if (entries.some((e) => e.isIntersecting)) { setSeen(true); io.disconnect(); } }, { threshold: 0.2 });
    io.observe(node);
    return () => io.disconnect();
  }, []);
  return [ref, seen];
}

/* ───────────── بطاقات الأرقام ───────────── */
function StatCard({ icon, target, lead, tail, label, active }) {
  const shown = useCountUp(target, active);
  return (
    <div className="bkc-stat">
      <span className="bkc-stat-ic"><Icon name={icon} size={24} /></span>
      <span className="bkc-stat-n" dir="ltr" aria-label={(lead || '') + target + (tail || '')}>{lead || ''}{shown}{tail || ''}</span>
      <span className="bkc-stat-l">{label}</span>
    </div>
  );
}

